css:
:scope { width: min(100%, 1086px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 24; grid-row: 1 / span 8; font-family: var(--os-font-heading); font-size: 59.2px; font-weight: 380; line-height: 1.08; letter-spacing: -0.015em; color: var(--os-color-text); }
.gx__i2 { grid-column: 1 / span 8; grid-row: 12 / span 80; aspect-ratio: 352 / 640; }
.gx__i3 { grid-column: 13 / span 8; grid-row: 12 / span 80; aspect-ratio: 352 / 640; }
.gx__i4 { grid-column: 1 / span 11; grid-row: 94 / span 5; font-family: var(--os-font-heading); font-size: 32px; font-weight: 380; line-height: 1.15; letter-spacing: -0.015em; color: var(--os-color-text); }
.gx__i5 { grid-column: 13 / span 11; grid-row: 94 / span 5; font-family: var(--os-font-heading); font-size: 32px; font-weight: 380; line-height: 1.15; letter-spacing: -0.015em; color: var(--os-color-text); }
.gx__i6 { grid-column: 1 / span 11; grid-row: 99 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: inherit; }
.gx__i7 { grid-column: 13 / span 11; grid-row: 99 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: inherit; }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-heading); font-size: 47px; }
  .gx__i4 { font-family: var(--os-font-heading); font-size: 26px; }
  .gx__i5 { font-family: var(--os-font-heading); font-size: 26px; }
  .gx__i6 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i7 { font-family: var(--os-font-label); font-size: 14px; }
}
